var meCoachSt = (st, p) => {
  if (!p || !p._ci) return st;
  const o = { ...st };
  for (const k in p._ci) {
    const r = ME_STRAT_RANGE[k] || [-2, 2];
    o[k] = Math.max(r[0], Math.min(r[1], (o[k] || 0) + p._ci[k]));
  }
  return o;
};
